{
  "predictors": [
    {
      "name": "CashFlowVolatility",
      "construction": "Standard deviation of quarterly cash flow from operations over the past three years, divided by average total assets over the same period.",
      "rationale": "Firms with more volatile cash flows might face higher financing costs or signal management's inability to control operations, leading to risk compensation.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "R&DIntensityTrend",
      "construction": "Linear trend coefficient of R&D expenses divided by sales over the last 5 years.",
      "rationale": "Increasing R&D intensity might indicate a firm's commitment to innovation, potentially leading to future growth.",
      "higher_returns_for": "positive trends"
    },
    {
      "name": "EmployeeGrowth",
      "construction": "Percentage change in total number of employees over the previous two years.",
      "rationale": "Rapid growth in employee numbers may signal expanding operations and future revenue growth.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "SupplierConcentration",
      "construction": "Herfindahl index based on the proportion of COGS attributed to the top three suppliers.",
      "rationale": "High supplier concentration may indicate potential supply chain risks, requiring higher returns as compensation.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "OperationalEfficiency",
      "construction": "Ratio of sales to administrative and selling expenses, calculated annually.",
      "rationale": "Higher ratios indicate better cost management, potentially leading to higher profitability.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "DividendDiscontinuity",
      "construction": "Binary variable indicating a dividend cut or omission in the past year.",
      "rationale": "Dividend cuts may signal financial distress or restructuring, leading to uncertainty and higher required returns.",
      "higher_returns_for": "presence of dividend discontinuity"
    },
    {
      "name": "DeferredRevenueGrowth",
      "construction": "Annual percentage change in deferred revenue from the balance sheet.",
      "rationale": "Increasing deferred revenue might indicate higher future revenue recognition and potential growth.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "CapitalExpenditureChange",
      "construction": "Change in capital expenditures as a percentage of total assets over the last two years.",
      "rationale": "Increased capital expenditure can signal future growth opportunities that the market hasn't fully priced in.",
      "higher_returns_for": "positive changes"
    },
    {
      "name": "ForeignSalesExposure",
      "construction": "Proportion of total sales generated from foreign markets in the most recent fiscal year.",
      "rationale": "Firms with higher foreign sales might benefit from diversified market exposure and potential currency gains.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "ShortInterestRatio",
      "construction": "Monthly short interest divided by average daily trading volume over the past month.",
      "rationale": "High short interest might indicate potential overvaluation, leading to higher future returns as the market corrects.",
      "higher_returns_for": "high values of the measure"
    }
  ]
}
